import os,json,urllib.request,urllib.error,sys,pathlib
ROOT=pathlib.Path(__file__).parent

def call(path,body=None,method=None,label=None):
 req=urllib.request.Request(os.environ['MCPJAM_API_URL'].rstrip('/')+path,data=json.dumps(body).encode() if body is not None else None,headers={'Authorization':'Bearer '+os.environ['MCPJAM_API_KEY'],'Content-Type':'application/json'},method=method)
 try:
  with urllib.request.urlopen(req,timeout=20) as r: status,data=r.status,r.read().decode()
 except urllib.error.HTTPError as e: status,data=e.code,e.read().decode()
 try: data=json.loads(data)
 except: pass
 result={'status':status,'body':data}
 if label: (ROOT/(label+'.json')).write_text(json.dumps(result,indent=2))
 print(json.dumps({'path':path,**result},indent=2));return result
if __name__=='__main__': call(sys.argv[1],json.load(open(sys.argv[2])) if len(sys.argv)>2 else None,label='response')
